steps.script:
$o=@()
foreach($n in @('ttittulares-mobile-trigger.log','ttendencias-mobile-trigger.log')){
 $p=Join-Path 'C:\TTiTTulares' $n
 $lines=@(Get-Content $p -Tail 200 -ErrorAction SilentlyContinue|Where-Object{$_ -match 'CHAT LAUNCH LOG ERROR|CHAT PROCESS EXITED|CHAT MESSAGE CONFIRMED' }|Select-Object -Last 4)
 foreach($line in $lines){
  $kind=if($line -match 'CHAT MESSAGE CONFIRMED'){'confirmed'}elseif($line -match 'CHAT PROCESS EXITED'){'exited'}else{'launch_error'}
  $tags=@('TOO_MANY_TABS','HARD_CAP','EDITORIAL_TAB_SOFT_PRESSURE','OTHER_CHAT_ACTIVITY','DRAFT_NOT_VERIFIED','AMBIGUOUS_PREVIOUS_SEND','No aparece el cuadro','NO_EDITOR','CDP','UNVERIFIED','Target','PREFLIGHT','COMPOSER','preflight_failed','another editorial','ERROR')
  $found=@($tags|Where-Object{$line.IndexOf($_,[StringComparison]::OrdinalIgnoreCase) -ge 0})
  $o+=@{file=$n;type=$kind;codes=$found;tail=$(if($kind -eq 'confirmed'){''}else{$x=$line -replace 'https?://\S+','[URL]' -replace '[A-Za-z0-9+/]{40,}={0,2}','[DATA]';$x.Substring([Math]::Max(0,$x.Length-180))})}
 }
}
Write-Output ('TTRESULT:'+(@{rows=$o}|ConvertTo-Json -Compress -Depth 5))
